// counter starts it at 1; every later call increments it by one under the
// same upsert, so two concurrent callers can never allocate the same value,
// even if one of them later rolls back.
func (q *Queries) NextCounterValue(ctx context.Context, counterName string) (int64, error) {
	row := q.db.QueryRow(ctx, nextCounterValue, counterName)
	var next_value int64
	err := row.Scan(&next_value)
	return next_value, err
}

